/** SPEC 63 GG-14: stress from sources that print it (core/stress-src.ts, pipelines/build-stress-src.ts): fixtures per source, conflict display, nothing generated by rule. */
import { describe, it, expect } from 'vitest'
import { existsSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { StBuilder, conflictLine, formStress, kaikkiCands, modernCand, parseAccented, r2uCands, stBucket, stGroups, stOfShard, sumCand } from '../core/stress-src.ts'
import { collectStress, stressSrcFiles, writeStressSrc } from '../pipelines/build-stress-src.ts'
import { renderStress } from '../core/text.ts'

const A = '́'
describe('GG-14 parsing', () => {
  it('GG-14 positions are indices of stressed vowels in the unstressed form; one word only', () => {
    expect(parseAccented(`лину${A}ти`)).toEqual({ word: 'линути', positions: [3] })
    expect(parseAccented('линути')).toBeUndefined()
    expect(parseAccented(`лину${A}ти хата`)).toBeUndefined()
    expect(parseAccented(`л${A}инути`)).toBeUndefined()
  })
})
describe('GG-14 sources', () => {
  it('GG-14 СУМ headword with stress (GG-7): only sum11 / sum20 rows, locator kept', () => {
    const c = sumCand('мати', { d: 'sum11', a: `ма${A}ти`, l: 'т.4 с.700' })!
    expect(c).toEqual({ lemma: 'мати', positions: [1], src: 'sum11', loc: 'т.4 с.700' })
    expect(sumCand('мати', { d: 'grinch', a: `ма${A}ти` })).toBeUndefined()
    expect(sumCand('мати', { d: 'sum20' })).toBeUndefined()
  })
  it('GG-14 r2u: Грінченко (uk-ru) takes the first article word; Уманець (ru-uk) takes single-word equivalents', () => {
    const g = r2uCands([12, 7, 'же', 'ukr', [`Лину${A}ти`], ['плыть'], `Лину${A}ти, ну${A}, неш, гл. / 1) Плыть.`], 'uk-ru', 'r2u', 'Грінченко')
    expect(g).toHaveLength(1); expect(g[0]).toMatchObject({ lemma: 'линути', positions: [3], src: 'hrinch' })
    expect(g[0]!.loc).toContain('#7')
    const u = r2uCands([9, 3, 'x', 'ukr', ['Видѣть'], [`турбува${A}тися`, `непоко${A}їтися`], ''], 'ru-uk', 'желехівка', 'Уманець')
    expect(u.map(x => x.lemma)).toEqual(['турбуватися', 'непокоїтися']); expect(u[0]!.src).toBe('umanets')
  })
  it('GG-14 old orthography: mapped only when the fold is unambiguous and vowels map one to one; an unaccented headword gives nothing', () => {
    const one = modernCand(`лѣ${A}то`, 'zheleh', 'x', 'желехівка')
    if (one) expect(one.positions).toHaveLength(1)
    expect(modernCand('лино', 'zheleh', 'x', 'желехівка')).toBeUndefined()
  })
  it('GG-14 kaikki: headword form with stress and stressed paradigm forms (CC BY-SA source)', () => {
    const k = kaikkiCands({ word: 'липа', lang_code: 'uk', forms: [{ form: `ли${A}па`, tags: ['canonical'] }, { form: 'lýpa', tags: ['romanization'] }, { form: `ли${A}пи`, tags: ['genitive', 'singular'] }, { form: `ли${A}п`, tags: ['genitive', 'plural'] }] }, 5)
    expect(k.lemma).toEqual([{ lemma: 'липа', positions: [1], src: 'kaikki', loc: expect.stringContaining('kaikki') }])
    expect(k.forms.map(f => f.form)).toEqual(['липи', 'лип']); expect(k.forms[0]!.positions).toEqual([1])
  })
})
describe('GG-14 shard, conflicts, no rule generation', () => {
  const b = new StBuilder()
  b.add({ lemma: 'мати', positions: [1], src: 'sum11', loc: 'т.4' }); b.add({ lemma: 'мати', positions: [3], src: 'hrinch', loc: 'r2u #1' }); b.add({ lemma: 'мати', positions: [1], src: 'kaikki', loc: 'w' })
  b.add({ lemma: 'вода', positions: [3], src: 'sum20', loc: 'т.1' })
  b.addForm({ lemma: 'вода', form: 'води', positions: [3], src: 'kaikki' })
  const m = b.finish(), sh = m.get(stBucket('мати'))!
  it('GG-14 each variant carries source + locator; the same stress from two sources is one group, different stress is a conflict with both sources', () => {
    const e = stOfShard(sh, 'Мати')![0]!
    expect(e.variants).toHaveLength(3); expect(e.variants[0]).toEqual({ positions: [1], src: 'sum11', loc: 'т.4' })
    const g = stGroups('мати', e.variants)
    expect(g).toHaveLength(2); expect(g[0]!.sources.map(s => s.src)).toEqual(['sum11', 'kaikki'])
    expect(conflictLine(g)).toBe(`наголос за СУМ-11, за en.wiktionary (kaikki, CC BY-SA 4.0): ${renderStress('мати', [1])}; за Грінченком: ${renderStress('мати', [3])}`)
    expect(conflictLine(stGroups('вода', [{ positions: [3], src: 'sum20', loc: '' }]))).toBe('')
  })
  it('GG-14 stressed forms are found by the plain form; a form no source stresses stays unstressed (no rule)', () => {
    const e = stOfShard(m.get(stBucket('вода'))!, 'вода')![0]!
    expect(formStress(e.forms, 'води')).toEqual([{ positions: [3], src: 'kaikki' }])
    expect(formStress(e.forms, 'воді')).toEqual([])
    expect(stOfShard(m.get(stBucket('вода'))!, 'невідоме')).toBeUndefined()
  })
  it('GG-14 no stress-by-rule code path: a lemma without a source gets no entry', () => {
    expect(new StBuilder().finish().size).toBe(0)
    expect(readFileSync('core/stress-src.ts', 'utf8')).not.toMatch(/penult|default stress/i)
  })
})
describe('GG-14 build step (RS-1)', () => {
  it('GG-14 collectStress reads СУМ + kaikki fixtures, writes atomically, reports a missing input instead of guessing', async () => {
    const root = mkdtempSync(join(tmpdir(), 'st-'))
    try {
      mkdirSync(resolve(root, 'data/work/se-parsed'), { recursive: true }); mkdirSync(resolve(root, 'data/raw/kaikki'), { recursive: true })
      writeFileSync(resolve(root, 'data/work/se-parsed/sum11.json'), JSON.stringify({ rows: [['липа', { d: 'sum11', g: 'x', a: `ли${A}па`, l: 'т.4' }], ['дім', { d: 'sum11', g: 'x' }]] }))
      writeFileSync(resolve(root, 'data/raw/kaikki/uk.jsonl'), JSON.stringify({ word: 'липа', lang_code: 'uk', forms: [{ form: `ли${A}па`, tags: [] }, { form: `ли${A}пи`, tags: ['genitive'] }] }) + '\n')
      const st = { bySrc: {}, skipped: {} as Record<string, number> }
      const s = writeStressSrc(root, await collectStress(root, new StBuilder(), st), st)
      expect(s.lemmas).toBe(1); expect(s.variants).toBe(2); expect(s.forms).toBe(1); expect(Object.keys(s.skipped).some(k => k.startsWith('r2u'))).toBe(true)
      const f = stressSrcFiles(root); expect(f).toHaveLength(1); expect(existsSync(resolve(root, 'data/work/stsrc.next'))).toBe(false)
      const e = stOfShard(JSON.parse(readFileSync(f[0]!, 'utf8')), 'липа')![0]!
      expect(e.variants.map(v => v.src).sort()).toEqual(['kaikki', 'sum11'])
    } finally { rmSync(root, { recursive: true, force: true }) }
  })
})
describe('GG-14 wiring', () => {
  it('GG-14 the build chain runs build-stress-src before build-parts, which shards it into lm/st; the card reads it lazily', () => {
    expect(readFileSync('package.json', 'utf8')).toMatch(/build-stress-src\.ts && tsx pipelines\/build-parts\.ts/)
    expect(readFileSync('pipelines/build-parts.ts', 'utf8')).toContain("fresh('lm/st')")
    expect(readFileSync('src/components/OvPronunciation.vue', 'utf8')).toContain('stOf(')
    expect(readFileSync('src/components/Paradigm.vue', 'utf8')).toContain('stressForms')
  })
})
